document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("business-days-form"),t=document.getElementById("business-days-result");e.addEventListener("submit",function(e){e.preventDefault();const n=new Date(document.getElementById("start-date").value),a=new Date(document.getElementById("end-date").value);if(!n||!a||n>a)return t.textContent="Please enter valid dates (start date must be before or equal to end date).",void 0;let d=0,s=0,o=0;const u=new Date(n);for(;u<=a;){const e=u.getDay();0===e||6===e?o++:s++,d++,u.setDate(u.getDate()+1)}const r=1===d?"day":"days",y=1===s?"day":"days",l=1===o?"day":"days";t.innerHTML=`\n      <b>Total calendar days:</b> ${d} ${r}<br>\n      <b>Business days:</b> ${s} ${y}<br>\n      <b>Weekend days (Saturday & Sunday):</b> ${o} ${l}\n    `})});